    e.preventDefault();
    setBusy(true);
    setError("");
    try {
      await onSubmit({
        url: url.trim(),
        title: title.trim(),
        notes: notes.trim(),
        tags: parseTags(tagsText),
      });
      if (!initial) {
        setUrl("");
        setTitle("");
        setNotes("");
        setTagsText("");
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : "Something went wrong.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <form className="form" onSubmit={handleSubmit}>
      <div className="form-row">
